-- Field officers (field_officer) register candidates in the field.
--
-- 1  Code: field_officer gets a referral code too, same as source_country.
--    Format PV + 6 characters, unique, generated by the database. A code sent
--    by the client is never accepted. The first code issued to a person stays
--    in private.staff_referral_codes and comes back when the role does.
--    Existing field officers get their code once (backfill at the end).
-- 2  registered_by: job_candidates.registered_by (staff_members.id). On
--    INSERT the server writes the calling staff member; a client value is
--    ignored. A field_officer or source_country caller also stamps their own
--    code. Upper management still chooses a code; the list now also holds
--    field officer codes (the portal shows them, lib/referralCode.ts).
--    Self-registration and anon inserts leave registered_by null.
--    registered_by and referral_code cannot change on UPDATE.
-- 3  KVKK: job_candidates.kvkk_recorded_by (staff_members.id). When staff
--    insert a candidate with kvkk_accepted_at set, kvkk_recorded_by is the
--    caller and kvkk_version the current text version ('2026-11-10',
--    lib/kvkk.ts KVKK_VERSION). kvkk_recorded_by is never taken from an app
--    client. The candidate's own consent (written by link_my_candidate from
--    the sign-up metadata) is not touched.
-- 4  Read scope: a field officer also SEES candidates they registered or
--    that carry their code. Only SELECT policies get this rule
--    (field_officer_owns_candidate). staff_can_read_candidate is NOT widened:
--    about fifteen write policies (candidate update, document update,
--    offers, interviews, matches, notifications, follow-ups, tickets) use it,
--    so widening it would hand out new write rights. Assigned / backup / task
--    rules stay as they are. Another officer's candidates stay hidden.
--    Field officers may now INSERT candidates (staff_can_insert_candidate).
--    On that insert, status, process fields and assignees are forced to their
--    defaults, so the insert opens no status or assignee write.
-- 5  Documents: on candidate_documents and the candidate-files bucket a field
--    officer may INSERT and SELECT for their own candidates (registered_by or
--    own code). UPDATE and DELETE policies are not touched. Every other
--    role keeps exactly the rule it had: the new rule is an OR that is true
--    only for field_officer.
--
-- Note: manager_delete_open_candidate deletes only rows with no code, so
-- candidates carrying a field officer's code cannot be deleted from the portal.
--
-- Idempotent: add column if not exists, create or replace, drop ... if exists.
-- Existing candidate rows are not changed. The only data change is the
-- one-time code backfill for field_officer staff rows.
--
-- Rollback: supabase/rollback/20261117100000_field_officer_registration_rollback.sql
-- Test (nothing kept): supabase/verification/field_officer_registration.sql
-- Do not apply this file from CI. Review it, then run it by hand.

begin;

do $$
begin
  if to_regclass('private.staff_referral_codes') is null then
    raise exception 'private.staff_referral_codes yok. Önce 20261104212539_source_country_referral_codes.sql. Hiçbir şey değiştirilmedi.';
  end if;
  if to_regprocedure('public.generate_supervisor_referral_code()') is null then
    raise exception 'public.generate_supervisor_referral_code() yok. Hiçbir şey değiştirilmedi.';
  end if;
  if to_regprocedure('public.current_staff()') is null
     or to_regprocedure('public.staff_can_read_candidate(uuid)') is null then
    raise exception 'current_staff() / staff_can_read_candidate() yok. Önce 20261110120000_staff_read_scope.sql. Hiçbir şey değiştirilmedi.';
  end if;
  if to_regprocedure('public.can_access_candidate_file(text)') is null
     or to_regprocedure('public.candidate_file_owner(text)') is null then
    raise exception 'can_access_candidate_file() yok. Önce 20261110121000_candidate_files_bucket.sql. Hiçbir şey değiştirilmedi.';
  end if;
end
$$;

-- 1. Columns ------------------------------------------------------------------

alter table public.job_candidates
  add column if not exists registered_by uuid references public.staff_members (id) on delete set null;

alter table public.job_candidates
  add column if not exists kvkk_recorded_by uuid references public.staff_members (id) on delete set null;

create index if not exists job_candidates_registered_by_idx
  on public.job_candidates (registered_by);

comment on column public.job_candidates.registered_by is
  'Staff member who registered the candidate. Written by the database on insert from the calling staff member; client values are ignored and it cannot change later. Null for self-registration and anon inserts.';
comment on column public.job_candidates.kvkk_recorded_by is
  'Staff member who recorded the candidate''s KVKK consent on a staff insert. Written by the database; never taken from an app client.';

-- 2. Staff codes: source_country and field_officer -----------------------------

-- The old check allows a code only for source_country. Drop it before codes
-- are given to field officers; it is added back at the end.
alter table public.staff_members
  drop constraint if exists staff_members_referral_code_role;

create or replace function public.assign_supervisor_referral_code()
returns trigger
language plpgsql
security definer
set search_path to ''
as $$
declare
  v_existing text;
begin
  if new.id is null then
    new.id := gen_random_uuid();
  end if;

  if new.role_level in ('source_country', 'field_officer') then
    select ledger.referral_code
      into v_existing
    from private.staff_referral_codes ledger
    where ledger.staff_id = new.id;

    if v_existing is not null then
      new.referral_code := v_existing;
    elsif tg_op = 'UPDATE'
       and old.role_level in ('source_country', 'field_officer')
       and old.referral_code ~ '^PV[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{6}$' then
      new.referral_code := old.referral_code;
    else
      new.referral_code := public.generate_supervisor_referral_code();
    end if;
    return new;
  end if;

  -- Other roles hold no live code. The ledger keeps an issued one.
  new.referral_code := null;
  return new;
end;
$$;

revoke all on function public.assign_supervisor_referral_code() from public, anon, authenticated, service_role;

create or replace function public.record_supervisor_referral_code()
returns trigger
language plpgsql
security definer
set search_path to ''
as $$
begin
  if new.role_level in ('source_country', 'field_officer')
     and new.referral_code ~ '^PV[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{6}$' then
    insert into private.staff_referral_codes (staff_id, referral_code)
    values (new.id, new.referral_code)
    on conflict (staff_id) do nothing;

    if exists (
      select 1
      from private.staff_referral_codes ledger
      where ledger.staff_id = new.id
        and ledger.referral_code is distinct from new.referral_code
    ) then
      raise exception 'referral_code_immutable' using errcode = '55000';
    end if;
  end if;
  return null;
end;
$$;

revoke all on function public.record_supervisor_referral_code() from public, anon, authenticated, service_role;

drop trigger if exists staff_members_assign_referral_code on public.staff_members;
create trigger staff_members_assign_referral_code
  before insert or update on public.staff_members
  for each row
  execute function public.assign_supervisor_referral_code();

drop trigger if exists staff_members_record_referral_code on public.staff_members;
create trigger staff_members_record_referral_code
  after insert or update on public.staff_members
  for each row
  execute function public.record_supervisor_referral_code();

comment on column public.staff_members.referral_code is
  'Unique code assigned by the database for a source_country or field_officer staff member. Null for every other role. Clients cannot choose or replace it.';

-- 3. Candidate insert: code, registered_by, KVKK --------------------------------

create or replace function public.stamp_candidate_referral_code()
returns trigger
language plpgsql
security definer
set search_path to ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_jwt text := coalesce((select auth.role()), '');
  v_staff_id uuid;
  v_role text;
  v_code text;
  v_supplied text;
  -- Same value as KVKK_VERSION in lib/kvkk.ts.
  v_kvkk_version constant text := '2026-11-10';
begin
  if tg_op = 'UPDATE' then
    new.referral_code := old.referral_code;
    new.registered_by := old.registered_by;
    new.kvkk_recorded_by := old.kvkk_recorded_by;
    return new;
  end if;

  v_supplied := nullif(btrim(coalesce(new.referral_code, '')), '');

  -- SQL editor and service role have no end-user actor. Anon never stamps anything.
  if v_uid is null then
    if v_jwt = 'service_role' or (v_jwt = '' and current_user in ('postgres', 'supabase_admin')) then
      if v_supplied is not null and exists (
        select 1 from public.staff_members s
        where s.referral_code = v_supplied
          and s.role_level in ('source_country', 'field_officer')
      ) then
        new.referral_code := v_supplied;
      else
        new.referral_code := null;
      end if;
    else
      new.referral_code := null;
      new.registered_by := null;
      new.kvkk_recorded_by := null;
    end if;
    return new;
  end if;

  -- Signed-in caller: the staff row from current_staff(), active only.
  select me.staff_id, me.role_level, me.referral_code
    into v_staff_id, v_role, v_code
  from public.current_staff() me
  join public.staff_members s on s.id = me.staff_id
  where coalesce(s.is_active, true)
  limit 1;

  -- Never from the client. Null for candidates and anyone who is not staff.
  new.registered_by := v_staff_id;
  new.kvkk_recorded_by := null;

  if v_staff_id is not null then
    if new.kvkk_accepted_at is not null then
      new.kvkk_recorded_by := v_staff_id;
      new.kvkk_version := v_kvkk_version;
    else
      new.kvkk_version := null;
    end if;
  end if;

  -- A field officer's insert opens no status or assignee write: same
  -- defaults a non-staff insert gets from guard_candidate_process_fields.
  if v_role = 'field_officer' then
    new.status := 'pending';
    new.official_process_status := null;
    new.travel_status := 'planned';
    new.flight_date := null;
    new.active_request_id := null;
    new.assigned_to := null;
    new.assigned_backup := null;
  end if;

  if v_role in ('source_country', 'field_officer') then
    if v_code is not null and v_code ~ '^PV[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{6}$' then
      new.referral_code := v_code;
      return new;
    end if;
    -- Same message the portal already explains for a missing officer code.
    raise exception 'source_officer_missing_code' using errcode = '23514';
  end if;

  if v_role = 'upper_management' or public.is_portal_manager() then
    if v_supplied is null then
      new.referral_code := null;
    elsif exists (
      select 1 from public.staff_members s
      where s.referral_code = v_supplied
        and s.role_level in ('source_country', 'field_officer')
    ) then
      new.referral_code := v_supplied;
    else
      raise exception 'unknown_supervisor_code' using errcode = '22023';
    end if;
    return new;
  end if;

  new.referral_code := null;
  return new;
end;
$$;

revoke all on function public.stamp_candidate_referral_code() from public, anon, authenticated, service_role;

drop trigger if exists job_candidates_stamp_referral_code on public.job_candidates;
create trigger job_candidates_stamp_referral_code
  before insert or update on public.job_candidates
  for each row
  execute function public.stamp_candidate_referral_code();

comment on column public.job_candidates.referral_code is
  'Set on insert from the acting staff member''s code (source_country or field_officer). Upper management may choose an existing officer code. Null is open or self registration. Updates cannot change it.';

-- 4. Read scope (SELECT only) and candidate insert --------------------------------

-- Row check: the caller is a field officer and registered this row or owns its code.
create or replace function public.field_officer_owns_candidate(p_registered_by uuid, p_referral_code text)
returns boolean
language sql
stable
security definer
set search_path to ''
as $$
  select exists (
    select 1
    from public.current_staff() me
    where me.role_level = 'field_officer'
      and (
        (p_registered_by is not null and p_registered_by = me.staff_id)
        or (me.referral_code is not null and p_referral_code = me.referral_code)
      )
  );
$$;

-- Same check by candidate id, for documents and file paths.
create or replace function public.field_officer_owns_candidate_id(p_id uuid)
returns boolean
language sql
stable
security definer
set search_path to ''
as $$
  select p_id is not null and exists (
    select 1
    from public.job_candidates c
    where c.id = p_id
      and public.field_officer_owns_candidate(c.registered_by, c.referral_code)
  );
$$;

create or replace function public.staff_can_insert_candidate()
returns boolean
language sql
stable
security definer
set search_path to ''
as $$
  select public.is_portal_manager()
    or exists (
      select 1 from public.current_staff() me
      where me.role_level in ('source_country', 'field_officer')
    );
$$;

revoke all on function public.field_officer_owns_candidate(uuid, text) from public, anon;
revoke all on function public.field_officer_owns_candidate_id(uuid) from public, anon;
revoke all on function public.staff_can_insert_candidate() from public, anon;
grant execute on function public.field_officer_owns_candidate(uuid, text) to authenticated;
grant execute on function public.field_officer_owns_candidate_id(uuid) to authenticated;
grant execute on function public.staff_can_insert_candidate() to authenticated;

-- The row check uses the row's own columns, so insert ... returning sees the new row.
drop policy if exists staff_select_candidates on public.job_candidates;
create policy staff_select_candidates on public.job_candidates
  for select to authenticated
  using (
    public.is_staff()
    and (
      public.staff_can_read_candidate(id)
      or public.field_officer_owns_candidate(registered_by, referral_code)
    )
  );

drop policy if exists staff_insert_candidates on public.job_candidates;
create policy staff_insert_candidates on public.job_candidates
  for insert to authenticated
  with check (public.is_staff() and public.staff_can_insert_candidate());

-- staff_update_candidates and manager_delete_open_candidate are not touched.

-- 5. Documents and files: INSERT and SELECT only ----------------------------------

drop policy if exists staff_select_documents on public.candidate_documents;
create policy staff_select_documents on public.candidate_documents
  for select to authenticated
  using (
    public.is_staff()
    and (
      public.staff_can_read_candidate(candidate_id)
      or public.field_officer_owns_candidate_id(candidate_id)
    )
  );

drop policy if exists staff_insert_documents on public.candidate_documents;
create policy staff_insert_documents on public.candidate_documents
  for insert to authenticated
  with check (
    public.is_staff()
    and (
      public.staff_can_read_candidate(candidate_id)
      or public.field_officer_owns_candidate_id(candidate_id)
    )
  );

-- staff_update_documents is not touched.

drop policy if exists candidate_files_select on storage.objects;
create policy candidate_files_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'candidate-files'
    and (
      public.can_access_candidate_file(name)
      or (public.is_staff() and public.field_officer_owns_candidate_id(public.candidate_file_owner(name)))
    )
  );

drop policy if exists candidate_files_insert on storage.objects;
create policy candidate_files_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'candidate-files'
    and (
      public.can_access_candidate_file(name)
      or (public.is_staff() and public.field_officer_owns_candidate_id(public.candidate_file_owner(name)))
    )
  );

-- candidate_files_update and candidate_files_delete are not touched.

-- 6. Backfill: field officers without a code get one now (once) ------------------

update public.staff_members
set updated_at = now()
where role_level = 'field_officer'
  and referral_code is null;

-- Back in place with the new role list. NOT VALID first so an unexpected live
-- row does not stop the migration; then validate and report.
alter table public.staff_members
  add constraint staff_members_referral_code_role
  check (
    (
      role_level in ('source_country', 'field_officer')
      and referral_code ~ '^PV[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{6}$'
    )
    or (
      role_level is distinct from 'source_country'
      and role_level is distinct from 'field_officer'
      and referral_code is null
    )
  ) not valid;

do $$
begin
  alter table public.staff_members validate constraint staff_members_referral_code_role;
exception when check_violation then
  raise notice 'staff_members_referral_code_role NOT VALID kaldı: kurala uymayan eski satır var. Yeni ve güncellenen satırlar yine denetlenir.';
end
$$;

do $$
declare
  v_missing int;
begin
  select count(*) into v_missing
  from public.staff_members
  where role_level = 'field_officer'
    and (referral_code is null or referral_code !~ '^PV[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{6}$');
  if v_missing > 0 then
    raise exception '% saha görevlisi kodsuz kaldı. Geri alındı.', v_missing;
  end if;
end
$$;

notify pgrst, 'reload schema';

commit;
